#define Ret(x,y) if(x<y)return 1; else if(x>y)return 0

const int maxk=31,MOD=int(1e9+7);

typedef int Mat[maxk][maxk];

int kb;

inline void mat_mul(Mat A,Mat B,Mat res) {
    static Mat C;
    memset(C,0,sizeof(C));
    REP(i,kb+1)REP(k,kb+1)REP(j,kb+1) {
        C[i][j]=(C[i][j]+(LL)A[i][k]*B[k][j])%MOD;
    }
    memcpy(res,C,sizeof(C));
}

Mat A[70][maxk],pre[maxk],suf[maxk],ans,I;
void init_I() {
    clr(I);
    REP(i,kb+1)I[i][i]=1;
}

int dig[70],len;

void prepocess() {
    REP(i,kb) {
        REP(j,kb+1) {
            A[0][i][j][j]=A[0][i][i][j]=1;
        }
    }
    FOR(i,1,len-1) {
        memcpy(pre[0],A[i-1][0],sizeof(A[i-1][0]));
        FOR(j,1,kb-1) {
            mat_mul(A[i-1][j],pre[j-1],pre[j]);
        }
        memcpy(suf[kb-1],A[i-1][kb-1],sizeof(A[i-1][kb-1]));
        PER(j,kb-2,0) {
            mat_mul(suf[j+1],A[i-1][j],suf[j]);
        }
        REP(j,kb) {
            mat_mul(j?pre[j-1]:I,suf[j],A[i][j]);
        }
    }
}

int main() {
    LL n=gint();
    kb=gint();
    init_I();
    while(n) {
        dig[len++]=n%kb;
        n/=kb;
    }
    prepocess();
    ans[kb][0]=1;
    int x=0;
    PER(i,len-1,0) {
        REP(j,dig[i]) {
            mat_mul(A[i][(j+x)%kb],ans,ans);
        }
        x=(x+dig[i])%kb;
    }
    int res=0;
    for(int i=0;i<kb;i++) {
        res=(res+ans[i][0])%MOD;
    }
    printf("%d\n",res+1);
    return 0;
}


